mod pipr_config;
use pipr_config::{PiprConfig, CONFIG_REFERENCE};

fn print_help(argv0: &str) {
    print!("Usage: {} [options]\n\nOptions:\n    -d, --default TEXT  text inserted into the textfield on startup\n    -o, --out-file FILE write final command to file\n        --in-file FILE  read initial command from file\n        --config-reference \n                        print out the default configuration file\n    -r, --raw-mode      keep linebreaks in finished command when closing\n        --no-isolation  disable isolation. This will run the commands directly\n                        on your system, without protection. Take care.\n    -h, --help          print this help menu\n", argv0);
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let argv0 = args.get(0).map(|s| s.as_str()).unwrap_or("./executable");
    // CLI parsing
    let mut default_val: Option<String> = None;
    let mut out_file: Option<String> = None;
    let mut in_file: Option<String> = None;
    let mut config_ref = false;
    let mut raw_mode = false;
    let mut no_isolation = false;
    let mut help = false;
    let mut seen_default = false;
    let mut seen_out = false;
    let mut seen_in = false;
    let mut seen_config_ref = false;
    let mut seen_raw = false;
    let mut seen_noiso = false;
    let mut seen_help = false;

    let mut i = 1;
    let mut end_options = false;
    let mut error: Option<String> = None;
    while i < args.len() {
        let a = &args[i];
        if end_options {
            i += 1;
            continue;
        }
        if a == "--" {
            end_options = true;
            i += 1;
            continue;
        }
        if a.starts_with("--") {
            // long option, possibly with =value
            let body = &a[2..];
            let (name, val_opt) = match body.find('=') {
                Some(pos) => (&body[..pos], Some(body[pos+1..].to_string())),
                None => (body, None),
            };
            match name {
                "default" => {
                    if seen_default { error = Some(format!("{}: Option 'default' given more than once\n", argv0)); break; }
                    seen_default = true;
                    if let Some(v) = val_opt {
                        default_val = Some(v);
                    } else {
                        if i+1 >= args.len() { error = Some(format!("{}: Argument to option 'default' missing\n", argv0)); break; }
                        i += 1;
                        default_val = Some(args[i].clone());
                    }
                },
                "out-file" => {
                    if seen_out { error = Some(format!("{}: Option 'out-file' given more than once\n", argv0)); break; }
                    seen_out = true;
                    if let Some(v) = val_opt {
                        out_file = Some(v);
                    } else {
                        if i+1 >= args.len() { error = Some(format!("{}: Argument to option 'out-file' missing\n", argv0)); break; }
                        i += 1;
                        out_file = Some(args[i].clone());
                    }
                },
                "in-file" => {
                    if seen_in { error = Some(format!("{}: Option 'in-file' given more than once\n", argv0)); break; }
                    seen_in = true;
                    if let Some(v) = val_opt {
                        in_file = Some(v);
                    } else {
                        if i+1 >= args.len() { error = Some(format!("{}: Argument to option 'in-file' missing\n", argv0)); break; }
                        i += 1;
                        in_file = Some(args[i].clone());
                    }
