pub fn relative_path(full: &PathBuf) -> String {
    let cwd = std::env::current_dir().unwrap_or(PathBuf::from("."));
    let full_str = full.to_string_lossy().to_string();
    let cwd_str = cwd.to_string_lossy().to_string();
    if let Some(s) = full_str.strip_prefix(&format!("{}/", cwd_str)) { return s.to_string(); }
    let cp: Vec<&str> = cwd_str.split('/').filter(|s| !s.is_empty()).collect();
    let fp: Vec<&str> = full_str.split('/').filter(|s| !s.is_empty()).collect();
    let mut c = 0;
    while c < cp.len() && c < fp.len() && cp[c] == fp[c] { c += 1; }
    let mut r = vec![".."; cp.len() - c];
    r.extend_from_slice(&fp[c..]);
    if r.is_empty() { return ".".to_string(); }
    r.join("/")
