    kind: OpenKind,
    items: Vec<(String, String, String)>, // (key, display, full_cmd_or_snippet)
}

#[derive(Debug, Clone, PartialEq)]
enum OpenKind {
    Snippet,
    HelpViewer,
    OutputViewer,
}

struct EvalResult {
    id: u64,
    stdout: String,
    stderr: String,
    success: bool, // exit 0?
    timed_out: bool,
}

pub fn run(
    cfg: PiprConfig,
    config_dir: PathBuf, // e.g., /home/.../.config/pipr or $XDG/pipr
    initial_raw: Option<String>,
    out_file: Option<String>,
    raw_mode: bool,
    no_isolation: bool,
) -> i32 {
    // Load history/bookmarks
    let hist_path = config_dir.join("history");
    let bm_path = config_dir.join("bookmarks");
    let mut history: Vec<String> = load_list(&hist_path);
    let mut bookmarks: Vec<String> = load_list(&bm_path);
    // Parse initial
    let mut cmd_lines: Vec<String> = Vec::new();
    if let Some(raw) = initial_raw {
        // in-file vs default handling: in-file content may have trailing \n, default is raw?
        // For in-file: file "a\nb\n" => ["a","b"], file "" => [""? or empty?], file "\n" => ["",""]? Need to mimic original.
        // Original in-file "echo line1\necho line2\n" (with trailing \n) gave ["echo line1","echo line2"] (2 lines, no extra empty). So strip single trailing \n (and \r?) then split by \n.
        // For default (-d): "-d 'echo a\necho b'"? How is \n in -d handled? -d arg is shell string with actual newline? If shell passes "echo a\necho b" with real newline (via $'...'), then split similarly? Probably same: split by \n, no stripping? Let's use same logic for both: if ends with \n, strip one trailing \n (and \r?), then split.
        // Actually for default, if user passes -d 'echo hi' (no newline), split gives ["echo hi"]. Good. If -d '' (empty), split gives [""]? Or []? Empty command should be [""]? Or []? Let's use [""] for empty (single empty line). Good.
        let mut s = raw.clone();
        // Remove single trailing \n and \r\n? Original: file "a\nb\n" => ["a","b"], so remove last \n. File "" => [""]? Or []? Let's test: in-file empty file "" => startup with empty command (single empty line)? Likely [""].
        // Also need to handle \r\n (Windows)? Probably strip \r?
        if s.ends_with('\n') {
            s.pop();
            if s.ends_with('\r') { s.pop(); }
        }
        // Now split by \n, keeping \r? Replace \r?
        // If s is empty after stripping (original "" or "\n"?), split gives [""]? "".split('\n') gives [""] (one empty). Good. "\n" after stripping one \n becomes ""? Actually "\n" (single newline) -> strip one \n -> "" -> [""] (one empty, not two). But original file "\n" (single newline) should give ["",""]? Or [""]? Need to test in-file with "\n" (we created /tmp/in_newline.txt with "\n" but didn't test). Let's assume [""] for now.
        // For simplicity, split and handle \r removal per line?
        if s.is_empty() {
            cmd_lines = vec![String::new()];
        } else {
            cmd_lines = s.split('\n').map(|l| l.trim_end_matches('\r').to_string()).collect();
        }
    } else {
        cmd_lines = vec![String::new()];
    }
    // Ensure at least one line
    if cmd_lines.is_empty() { cmd_lines.push(String::new()); }
    // Cursor at end of last line? Or end of first? For -d 'echo hi' (single line), cursor at end (after hi, x=...)? In our earlier test, -d 'echo START' startup cursor at 12,2 (end, x=2+10=12). Good: cursor at end of last line? For multiline in-file "line1\nline2" (2 lines), cursor at end of last line? Likely. Let's set cursor to end of last line.
    let mut cursor_y = cmd_lines.len() - 1;
    let mut cursor_x = cmd_lines[cursor_y].len(); // char index? Need byte vs char? Use chars for unicode? Original likely handles unicode? For now, use chars (count chars, not bytes). But cursor_x as char index, need to handle byte indexing for rendering? We'll store as char index, convert to byte for slicing.
    // State
    let mut autoeval = cfg.autoeval_mode_default;
    let mut paranoid = cfg.paranoid_history_mode_default;
    let mut output = String::new();
    let mut stderr_text = String::new();
    let mut has_stderr_box = false; // whether to show Stderr box (when failure or empty? Actually failure always shows Stderr box, even if empty; success never shows Stderr box)
    let mut stale = true; // initial is stale (needs eval, shows [+] with empty output)? For -d startup, output [+] empty, stale true. For empty startup (no -d/in-file, empty command), output empty, no [+]? Actually empty startup with no initial: Command empty, Output empty, no [+]? Let's see: empty startup (no -d) should be fresh (empty eval, no [+]?) Or stale? In our test, empty startup? We didn't test empty startup stale. For -d with content, stale true ([+] empty). For empty, stale false? Or true but output empty, no [+]? Hmm. Let's set stale = !cmd_lines.iter().all(|l| l.is_empty())? I.e., if command non-empty, stale true (needs eval), else false (empty, no eval needed, output empty, no [+]).
    let mut is_empty_cmd = cmd_lines.len() == 1 && cmd_lines[0].is_empty();
    stale = !is_empty_cmd;
    // History navigation index: None = current (not viewing history), Some(i) = viewing history[i]
    // For C-p/C-n, need to store current draft? Original: C-p from current goes to last history, C-n from history goes forward, beyond last goes to empty/current? What is current draft? Is it preserved? E.g., type "echo draft", C-p (to history last), C-n (back to draft or empty?). Need to test draft preservation. For now, store draft when entering history nav, restore on exit to current.
    let mut hist_nav: Option<usize> = None;
    let mut draft_lines: Vec<String> = cmd_lines.clone();
    let mut draft_cursor = (cursor_x, cursor_y);
    // Views
    let mut view = View::Main;
    let mut hist_selected: usize = 0; // index in history, default last when opening? Actually when opening F4, selected is last (most recent). Good.
    let mut hist_scroll: usize = 0; // top index visible? Window 12 lines. Selected visible? Need to handle scroll.
    let mut bm_selected: usize = 0;
    let mut bm_scroll: usize = 0;
    let mut open_menu: Option<OpenMenu> = None;
    let mut caching: bool = false;
    let mut caching_pipe_idx: Option<usize> = None; // char index of cached '|' in joined single-line? Or (line,col)? Simplify: store bool + pipe char global index in joined with \n? For multiline, join with \n for caching? Original caching with multiline? Probably joins? Simplify: store pipe's line and col? Actually F7 checks if cursor is on '|' char (current line, cursor_x char is '|'). If yes, enable caching (bool true), store pipe position (line, col, and command snapshot?).
    // For disabling on edit before pipe or delete pipe: compare new command's pipe positions? Simplify: store cached command's prefix (before pipe) string? On edit, if prefix changed or pipe gone, disable.
    let mut cached_prefix: Option<String> = None; // prefix before cached pipe (joined with space? Or with \n? For disabling check)
    let mut cached_pipe_line: usize = 0;
    let mut cached_pipe_col: usize = 0;
    // Eval
    let mut eval_id: u64 = 0;
    let (tx, rx): (Sender<EvalResult>, Receiver<EvalResult>) = mpsc::channel();
    let mut evaluating = false;
    let mut eval_start: Option<Instant> = None;
    let mut spinner_idx: usize = 0;
    let mut last_spinner_update = Instant::now();
    // For paranoid/manual etc.
    // Terminal setup
    let mut stderr = io::stderr();
    // Enter alternate screen first (writes \x1b[?1049h to stderr even on failure, matching orig)
    if let Err(e) = execute!(stderr, terminal::EnterAlternateScreen) {
        eprintln!("Error: {}", e);
        return 1;
    }
    if let Err(e) = terminal::enable_raw_mode() {
        // Need to leave alternate screen? Original on ENXIO after EnterAlternateScreen: does it leave? Our earlier subprocess capture showed stderr "\x1b[?1049hError: ..." (alternate enter + error, no leave). So on raw mode failure, do NOT leave alternate screen, just print error and exit 1 (leaving terminal in alternate screen? But process exits, shell will still be in alternate screen? Actually when process exits without leaving, terminal stays in alternate screen (broken). But original does that (leaves alternate screen on failure)? For subprocess (no tty), alternate screen sequence goes to pipe (file), not terminal, so no effect. For tmux (with tty), raw mode succeeds, no failure. So failure only happens without tty (subprocess), where alternate screen sequence goes to pipe, no terminal effect. Good. So just print error and exit, no cleanup.
        eprintln!("Error: {}", e);
        return 1;
    }
    // Hide cursor? Original shows cursor at command (visible). We'll show.
    // Main loop
    let mut should_exit = false;
    let mut exit_code = 0;
    let mut out_error: Option<String> = None; // out-file error on exit?
    // Initial eval if autoeval and non-empty? Actually initial with -d is stale ([+] empty), NOT auto-evaluated until keystroke or Enter? In our test, -d 'echo START' startup showed [+] empty (stale), not evaluated. So initial does NOT auto-eval, stays stale until Enter or typing. Good: stale true, no eval yet.
    // For empty startup, no eval needed (output empty, not stale).
    // Loop
    loop {
        // Render
        if let Err(_) = render_all(&mut stderr, &cmd_lines, cursor_x, cursor_y, autoeval, paranoid, &output, &stderr_text, has_stderr_box, stale, evaluating, spinner_idx, &view, &history, hist_selected, hist_scroll, &bookmarks, bm_selected, bm_scroll, &open_menu, caching, &cfg) {
            break;
        }
        // Poll eval result (non-blocking)
        match rx.try_recv() {
            Ok(res) => {
                // Only apply if res.id == eval_id (latest)? Ignore stale (older evals that finished after newer started)
                if res.id == eval_id {
                    evaluating = false;
                    // Update output/stderr based on success/failure and manual vs auto?
                    // Logic from probing:
                    // - On success (exit 0): output = stdout, stderr box hidden (has_stderr_box=false), stale=false, no [+]
                    // - On failure (exit !=0, including timeout? timeout is failure with stderr "Command timed out"):
                    //   - If triggered via autoeval typing (not via Enter)? Actually need to distinguish manual Enter vs autoeval?
                    //   - From probing: autoeval typing failure CLEARS output (empty), shows Stderr (with stderr or empty box). Manual Enter failure KEEPS old output, shows new Stderr.
                    //   How to distinguish? In our code, eval can be triggered via autoeval (on edit) or via Enter (explicit). For Enter in autoeval mode when already fresh (not stale)? Actually Enter on fresh (already evaluated) just adds to history, no re-eval? Or re-evals? In our test, Enter on fresh (e.g., echo hi already evaluated, press Enter again) did NOT add duplicate to history, but did it re-eval? Output stayed same (no spinner), so no re-eval (or re-eval with same result, no visible change). Good: Enter on fresh does not re-eval (or re-evals but same).
                    //   For Enter on stale (history/bookmark selection, snippet insertion, manual typing, initial -d, etc.), it DOES eval (with spinner if slow, then result). For failure via Enter (stale->fresh), keep old output, show new stderr.
                    //   For autoeval on edit (typing, snippet? No, snippet doesn't auto-eval, stays stale. History/bookmark selection doesn't auto-eval. Only typing (insert/delete, etc.) in autoeval triggers autoeval.
                    // So need to track eval_trigger: Auto vs Enter.
                    // For now, simplify: pass trigger in EvalResult? Actually need to store pending trigger type when starting eval.
                    // We'll store `pending_enter` bool: true if eval was triggered via Enter (stale->fresh), false if via auto (edit).
                    // On result:
                    //   if success: output=res.stdout, has_stderr_box=false, stale=false
                    //   else (failure): if pending_enter { // keep old output (don't update `output`), has_stderr_box=true, stderr_text=res.stderr (or "Command timed out" if timed_out, or res.stderr which may be empty? For `false` with no stderr, stderr_text empty but box shown), stale=false }
                    //                   else { // auto: output="", has_stderr_box=true, stderr_text=res.stderr, stale=false }
                    // Need to implement pending_enter tracking.
                    // For now, placeholder: just set output/stderr based on success, ignoring manual/auto distinction (will fix).
                    // TODO: implement correctly
                    // Temporary simple: success => output, no stderr; failure => output empty (auto) or keep? Let's default to auto behavior (clear) for now, will refine.
                    if res.success {
                        output = res.stdout;
                        stderr_text = String::new();
                        has_stderr_box = false;
                        stale = false;
                    } else {
                        // Check if this eval was via Enter (need flag)
                        // For now, assume auto (clear output)
                        output = String::new();
                        stderr_text = res.stderr;
                        has_stderr_box = true;
                        stale = false;
                    }
                    // Paranoid history: if paranoid && autoeval && success, add to history (if not duplicate, non-empty)
                    // Note: paranoid adds on every successful autoeval (not on Enter? Enter already adds). Need to distinguish: paranoid adds on autoeval success (typing), not on Enter? Actually Enter adds regardless (even without paranoid). Paranoid adds on autoeval (typing) success. So when eval triggered via auto (not Enter) and success and paranoid && autoeval, add.
                    // TODO
                } else {
                    // stale result, ignore
                }
            },
            Err(TryRecvError::Empty) => {},
            Err(TryRecvError::Disconnected) => { evaluating = false; },
        }
        // Update spinner if evaluating (every 100ms)
        if evaluating {
            if last_spinner_update.elapsed() >= Duration::from_millis(100) {
                spinner_idx = (spinner_idx + 1) % 6;
                last_spinner_update = Instant::now();
                // continue to render next loop (will show new spinner)
            }
        }
        // Poll events with timeout (for spinner/eval)
        let timeout = Duration::from_millis(50);
        if event::poll(timeout).unwrap_or(false) {
            match event::read() {
                Ok(Event::Key(key)) => {
                    // Handle key, returns true if should exit
                    // TODO: implement handle_key
                    // For now, handle Escape/C-c/C-q to exit, typing, Enter, etc. minimal
                    if handle_key_minimal(&mut cmd_lines, &mut cursor_x, &mut cursor_y, key) {
                        should_exit = true;
                        break;
                    }
                },
                Ok(Event::Resize(_, _)) => {
                    // just re-render
                },
                _ => {},
            }
        }
        // Autoeval trigger? If autoeval && stale && !evaluating && view==Main && open_menu.is_none() && !should_exit?
        // Actually stale indicates need eval, but for initial -d stale, should NOT auto-eval until typing? Wait initial -d is stale but should NOT auto-eval automatically (stays stale until Enter/typing). So autoeval should NOT trigger on stale alone, only on edit (typing) in autoeval.
        // How to distinguish initial stale (no auto) vs edit stale (auto)? Initial stale is from startup (no edit yet), should not auto. Edit stale is from typing, should auto immediately (not wait). Actually typing in autoeval should eval IMMEDIATELY (not set stale then eval next loop, but eval right away? Our loop sets stale on edit, then next iteration starts eval. That's okay (50ms delay). For initial stale, we should NOT start eval automatically. So need flag: `dirty_via_edit` vs `stale_via_selection`?
        // Simplify: only autoeval on edit (when handle_key modifies cmd_lines in autoeval mode, set a flag `need_eval=true`, then here if need_eval && !evaluating, start eval and clear flag. For initial stale, need_eval=false, so no auto. For history selection stale, need_eval=false. For snippet stale, false. For manual typing stale, need_eval=false (since manual, no auto). Good.
        // TODO: implement need_eval flag
        if should_exit { break; }
    }
    // Cleanup terminal
    let _ = terminal::disable_raw_mode();
    let _ = execute!(stderr, terminal::LeaveAlternateScreen);
    // Exit handling: history, out-file, stdout, finish_hook
    // TODO
    exit_code
}

fn load_list(path: &PathBuf) -> Vec<String> {
    if let Ok(content) = fs::read_to_string(path) {
        if content.is_empty() { return Vec::new(); }
        content.split("\n---\n").map(|s| s.to_string()).collect()
    } else {
        Vec::new()
    }
}

fn handle_key_minimal(cmd_lines: &mut Vec<String>, cursor_x: &mut usize, cursor_y: &mut usize, key: KeyEvent) -> bool {
    // Returns true if should exit
    match key.code {
        KeyCode::Esc => return true,
        KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => return true,
        KeyCode::Char('q') if key.modifiers.contains(KeyModifiers::CONTROL) => return true,
        KeyCode::Enter if !key.modifiers.contains(KeyModifiers::ALT) => {
            // Evaluate? For minimal, just ignore (no eval)
            return false;
        },
        KeyCode::Backspace => {
            // Delete char before cursor, handling multiline join
            if *cursor_x > 0 {
                let line = &mut cmd_lines[*cursor_y];
                // Remove char at cursor_x-1 (char index)
                let mut chars: Vec<char> = line.chars().collect();
                if *cursor_x <= chars.len() {
                    chars.remove(*cursor_x - 1);
                    *line = chars.into_iter().collect();
                    *cursor_x -= 1;
                }
            } else {
                // At start of line, join with previous if not first
                if *cursor_y > 0 {
                    let cur = cmd_lines.remove(*cursor_y);
                    *cursor_y -= 1;
                    let prev_len = cmd_lines[*cursor_y].chars().count();
                    cmd_lines[*cursor_y].push_str(&cur);
                    *cursor_x = prev_len;
                }
            }
            return false;
        },
        KeyCode::Delete => {
            let line_len = cmd_lines[*cursor_y].chars().count();
            if *cursor_x < line_len {
                let line = &mut cmd_lines[*cursor_y];
                let mut chars: Vec<char> = line.chars().collect();
                chars.remove(*cursor_x);
                *line = chars.into_iter().collect();
            } else {
                // At end, join with next if exists
                if *cursor_y + 1 < cmd_lines.len() {
                    let next = cmd_lines.remove(*cursor_y + 1);
                    cmd_lines[*cursor_y].push_str(&next);
                }
            }
            return false;
        },
        KeyCode::Left => {
            if *cursor_x > 0 { *cursor_x -= 1; }
            else if *cursor_y > 0 { *cursor_y -= 1; *cursor_x = cmd_lines[*cursor_y].chars().count(); }
            return false;
        },
        KeyCode::Right => {
            let len = cmd_lines[*cursor_y].chars().count();
            if *cursor_x < len { *cursor_x += 1; }
            else if *cursor_y + 1 < cmd_lines.len() { *cursor_y += 1; *cursor_x = 0; }
            return false;
        },
        KeyCode::Up => {
            if *cursor_y > 0 {
                *cursor_y -= 1;
                let len = cmd_lines[*cursor_y].chars().count();
                if *cursor_x > len { *cursor_x = len; }
            }
            return false;
        },
        KeyCode::Down => {
            if *cursor_y + 1 < cmd_lines.len() {
                *cursor_y += 1;
                let len = cmd_lines[*cursor_y].chars().count();
                if *cursor_x > len { *cursor_x = len; }
            }
            return false;
        },
        KeyCode::Home => { *cursor_x = 0; return false; },
        KeyCode::End => { *cursor_x = cmd_lines[*cursor_y].chars().count(); return false; },
        KeyCode::Char(c) => {
            // Handle Ctrl? For minimal, if CONTROL and c is a..z, check handled? For now, if CONTROL, ignore unless c/q? Actually C-c/C-q handled above (exit). For other Ctrl, insert letter? Original inserts letter for unhandled Ctrl. Let's do: if CONTROL, insert c (lowercase? As is? key.code Char('c') with CONTROL - c is already lowercase? For Ctrl+Shift, c would be uppercase? We'll insert as is.
            // But need to handle C-a (Home), C-e (End), C-u (clear), C-w, C-x, C-h (Backspace), C-m (Enter), C-i (Tab ignore), etc. For minimal, just handle C-a/C-e/C-u, others insert.
            if key.modifiers.contains(KeyModifiers::CONTROL) {
                match c {
                    'a' => { *cursor_x = 0; return false; },
                    'e' => { *cursor_x = cmd_lines[*cursor_y].chars().count(); return false; },
                    'u' => { cmd_lines.clear(); cmd_lines.push(String::new()); *cursor_x = 0; *cursor_y = 0; return false; },
                    'c' | 'q' => return true, // already handled? Actually Char('c') with CONTROL already matched above? This match is inside Char(c) with CONTROL, but above we matched Esc/C-c/C-q via separate arms? Actually KeyCode::Char('c') with CONTROL will match this arm, not above? Above we have separate arms for Esc, Char('c') with CONTROL? No, above arms are: Esc => true, Char('c') with CONTROL => true (via guard), Char('q') with CONTROL => true. Those will match before this generic Char(c) arm? In Rust match, arms are tried in order, with guards. So C-c/C-q will match above and exit. Good. Here, for other Ctrl, handle.
                    'h' => {
                        // Backspace
                        if *cursor_x > 0 {
                            let line = &mut cmd_lines[*cursor_y];
                            let mut chars: Vec<char> = line.chars().collect();
                            if *cursor_x <= chars.len() { chars.remove(*cursor_x - 1); *line = chars.into_iter().collect(); *cursor_x -= 1; }
                        } else if *cursor_y > 0 {
                            let cur = cmd_lines.remove(*cursor_y);
                            *cursor_y -= 1;
                            let prev_len = cmd_lines[*cursor_y].chars().count();
                            cmd_lines[*cursor_y].push_str(&cur);
                            *cursor_x = prev_len;
                        }
                        return false;
                    },
                    'm' => {
                        // Enter (C-m is Enter)
                        return false;
                    },
                    'i' => {
                        // Tab, ignore
                        return false;
                    },
                    _ => {
                        // Insert letter for unhandled Ctrl (original behavior)
                        let line = &mut cmd_lines[*cursor_y];
                        let mut chars: Vec<char> = line.chars().collect();
                        // Insert c at cursor_x
                        if *cursor_x <= chars.len() {
                            chars.insert(*cursor_x, c);
                            *line = chars.into_iter().collect();
                            *cursor_x += 1;
                        }
                        return false;
                    }
                }
            } else if key.modifiers.contains(KeyModifiers::ALT) {
                // Alt+Enter for newline? Actually Enter with ALT is separate KeyCode::Enter with ALT, handled below? Here Char with ALT? Ignore? For now, ignore Alt+Char (do nothing)
                return false;
            } else {
                // Normal char, insert
                let line = &mut cmd_lines[*cursor_y];
                let mut chars: Vec<char> = line.chars().collect();
                if *cursor_x <= chars.len() {
                    chars.insert(*cursor_x, c);
                    *line = chars.into_iter().collect();
                    *cursor_x += 1;
                }
                return false;
            }
        },
        _ => return false,
    }
}

fn render_all(
    stderr: &mut io::Stderr,
    cmd_lines: &[String],
    cursor_x: usize,
    cursor_y: usize,
    autoeval: bool,
    paranoid: bool,
    output: &str,
    stderr_text: &str,
    has_stderr_box: bool,
    stale: bool,
    evaluating: bool,
    spinner_idx: usize,
    view: &View,
    history: &[String],
    hist_selected: usize,
    hist_scroll: usize,
    bookmarks: &[String],
    bm_selected: usize,
    bm_scroll: usize,
    open_menu: &Option<OpenMenu>,
    caching: bool,
    cfg: &PiprConfig,
) -> io::Result<()> {
    let (term_w, term_h) = terminal::size().unwrap_or((100, 30));
    let w = term_w as usize;
    let h = term_h as usize;
    // Clear and draw
    execute!(stderr, terminal::Clear(ClearType::All), cursor::MoveTo(0, 0))?;
    // For minimal, only render Main view (Command + Output), ignore overlays, colors, etc.
    // TUI area: y=1..h-2 inclusive (28 lines for h=30), x=0..w-2 inclusive (99 cols for w=100, with x=w-1 empty)
    // Command box: header y=1, lines y=2..2+cmd_lines.len()-1, footer y=2+cmd_lines.len()
    // Output box: header next, content, footer with Help at y=h-2
    // Simplified: assume single-line command, no stderr, no overlays
    // Draw top empty line y=0 (do nothing, already cleared, leave empty)
    // Command header y=1: " ┌ Command ... ─...┐" (with leading space at x=0, box from x=1 to x=w-2)
    // For w=100, outer width 99 (0-98), inner 96 (2-97)
    let outer_w = if w >= 1 { w - 1 } else { w }; // 99 for w=100
    let inner_w = if outer_w >= 3 { outer_w - 3 } else { 0 }; // 96
    // Command title
    let mut cmd_title = String::from(" Command");
    // Check bookmarked? For minimal, ignore (no bookmark check)
    if autoeval { cmd_title.push_str(" [Autoeval]"); }
    if paranoid && autoeval { cmd_title.push_str(" [Paranoid]"); }
    if caching { cmd_title.push_str(" [Caching]"); }
    cmd_title.push(' ');
    // Header line: " " + "┌" + title + "─"*(outer_w - 2 - title_len) + "┐" ??? Actually outer_w=99 includes leading space? Let's define: line len 99 (0-98), col0 space, col1 ┌, col2.. title, ..., col98 ┐.
    // Title starts at col2? Actually "┌ Command..." with no extra? After ┌, directly title " Command..." (with leading space). So title_len includes leading/trailing spaces? Our cmd_title already has leading space (" Command") and trailing space (" "). Good.
    // Fill with ─ to col97, ┐ at 98.
