fn join_for_eval(cmd_lines: &[String]) -> String {
    // Filter lines starting with '#' (col0), join remaining with single space " "
    let filtered: Vec<&str> = cmd_lines.iter().filter(|l| !l.starts_with('#')).map(|s| s.as_str()).collect();
