fn do_eval(cmd_lines: Vec<String>, cfg: &PiprConfig, no_isolation: bool, id: u64) -> EvalResult {
    let joined = join_for_eval(&cmd_lines);
    // Handle empty eval_environment
    if cfg.eval_environment.is_empty() {
        return EvalResult { id, stdout: String::new(), stderr: "shell_command is empty".to_string(), success: false, timed_out: false };
    }
    // Build command: bwrap or direct
    let mut cmd: Command;
    if !no_isolation {
        // bwrap --ro-bind / / --tmpfs /tmp --dev /dev --proc /proc --die-with-parent --share-net --unshare-pid <eval_env> <joined>
        cmd = Command::new("bwrap");
        cmd.arg("--ro-bind").arg("/").arg("/");
        cmd.arg("--tmpfs").arg("/tmp");
        cmd.arg("--dev").arg("/dev");
        cmd.arg("--proc").arg("/proc");
        cmd.arg("--die-with-parent");
        cmd.arg("--share-net");
        cmd.arg("--unshare-pid");
        for e in &cfg.eval_environment {
            cmd.arg(e);
        }
        cmd.arg(&joined);
    } else {
        // direct: <eval_env[0]> <eval_env[1..]> <joined>
        // eval_env[0] is binary, rest are args, plus joined as last arg
        let prog = &cfg.eval_environment[0];
        cmd = Command::new(prog);
        for e in cfg.eval_environment.iter().skip(1) {
            cmd.arg(e);
        }
        cmd.arg(&joined);
    }
    cmd.stdout(Stdio::piped()).stderr(Stdio::piped());
    // Spawn
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(_) => {
            return EvalResult { id, stdout: String::new(), stderr: "Unable to spawn command".to_string(), success: false, timed_out: false };
        }
    };
    // Wait with timeout
    let timeout = Duration::from_millis(cfg.cmd_timeout_millis);
    // Use wait-timeout crate? Need to import. For now, use std::thread + wait? Actually need wait_timeout::ChildExt.
    // We'll use wait_timeout crate (already in Cargo.toml).
    use wait_timeout::ChildExt;
    match child.wait_timeout(timeout) {
        Ok(Some(status)) => {
            // Finished within timeout, get output (need to read stdout/stderr? wait_timeout's wait_timeout doesn't capture output, need to have piped and read? Actually Command::spawn with piped stdout/stderr, then wait_timeout waits, but output not yet read. Need to read via child.stdout/stderr? Simpler: use output() with timeout? But output() blocks without timeout. Need to handle.
