                let mut buf = Vec::new();
                let _ = err.read_to_end(&mut buf);
                err_str = String::from_utf8_lossy(&buf).to_string();
            }
            let success = status.success();
            EvalResult { id, stdout: out_str, stderr: err_str, success, timed_out: false }
        },
        Ok(None) => {
            // Timeout, kill
            let _ = child.kill();
            let _ = child.wait(); // reap
            EvalResult { id, stdout: String::new(), stderr: String::new(), success: false, timed_out: true }
        },
        Err(_) => {
            // Error waiting? Treat as failure with Unable?
            let _ = child.kill();
            EvalResult { id, stdout: String::new(), stderr: "Unable to spawn command".to_string(), success: false, timed_out: false }
        }
    }
}
