    // Logic:
    // - Convert line to chars vec.
    // - If cursor_x < len and chars[cursor_x] != ' ' (on word char), find word boundaries: start = cursor_x backwards until space or 0, end = cursor_x forwards until space or len. Return chars[start..end] as String.
    // - Else (cursor on space or at end beyond len? Actually cursor_x == len means after last char (end). If last char is space? Or word? For end after word (e.g., "echo hi" len 7? Actually "echo hi" len 7? e0 c1 h2 o3 space4 h5 i6, len 7? Wait len 7? "echo hi" = 7 chars (0-6), len 7, cursor at end =7 (beyond last). Previous char at 6 is 'i' (word char), so previous word is "hi". Good: return previous word.
    //   If cursor on space (chars[cursor_x]==' '), find previous word: scan left from cursor_x-1 backwards skipping spaces? Or immediate left? In our test, space at pos4 (after echo) gave "echo" (left word, immediate, no skipping? Actually pos4 is space, left is "echo" (0-3), no spaces to skip (just one space). What about multiple spaces? E.g., "echo   hi" (3 spaces between), cursor on middle space (pos6? echo(0-3) space4 space5 space6 hi7-8, cursor at 6 (middle space), previous word? Immediate left is space (pos5 space), not word. Should it skip spaces to find "echo"? Or return None (since immediate left is space)? Our earlier test with "hello   world" (3 spaces) and C-w? Not F5. For F5 on middle space, what does original do? Likely returns previous word ("echo" or "hello") by skipping spaces? Or returns None? Need to test F5 on middle of multiple spaces. For now, implement: skip spaces left to find word end, then find start. If no word found (all spaces before), None.
    // - If cursor at 0 and chars[0]==' ' (leading space), previous word None (no word before), return None? Or next word to right? Original on space uses left (previous), not right. So leading space gives None (no menu). Good.
    let chars: Vec<char> = cmd_line.chars().collect();
    let len = chars.len();
    if len == 0 { return None; }
    if cursor_x < len && chars[cursor_x] != ' ' {
        // on word
        let mut start = cursor_x;
        while start > 0 && chars[start-1] != ' ' { start -= 1; }
        let mut end = cursor_x;
        while end < len && chars[end] != ' ' { end += 1; }
        Some(chars[start..end].iter().collect())
    } else {
        // on space or at end (cursor_x==len, beyond)
        // Find previous word end: scan left from cursor_x-1 (or len-1 if at end) skipping spaces?
        let mut idx = if cursor_x == 0 { return None; } else if cursor_x > len { len } else { cursor_x };
        // idx is cursor position (0..len, where len means after last). Previous char is at idx-1.
        // Skip spaces left?
        // Actually for cursor on space at pos4 (space), idx=4, previous char at 3 is 'o' (word), no spaces to skip (immediate left is word). Good: find word end at idx-1 if non-space, else skip spaces?
        // If cursor on space with immediate left also space (multiple spaces), skip spaces to find word?
        let mut end = idx;
        // Move end left while previous is space? Actually end is exclusive (one past word end). Start with end=idx (cursor), move left while chars[end-1]==' ' (skip spaces).
        while end > 0 && chars[end-1] == ' ' { end -= 1; }
        if end == 0 { return None; } // all spaces before, no word
        // Now chars[end-1] is word char (end of word), find start
        let mut start = end;
        while start > 0 && chars[start-1] != ' ' { start -= 1; }
        Some(chars[start..end].iter().collect())
    }
